-- StarRocks 物化视图 v2：库 indicators；5 院区 UNION（HID0101/0103/0117/0120 + 公卫 HID0122）
-- fsjcl_v2 仅本部 hid0101_mssql RIS/超声，公卫无同源库未并入

CREATE MATERIALIZED VIEW `indicators`.`currentcyxz_v2` (`hosp_code`, `paadm_depcode_dr`, `ctloc_code`, `ctloc_desc`, `ward_code`, `ward_desc`, `sscyresult`, `lastupdatedttm`)
COMMENT "实时出院人次汇总"
