WHERE (((`hid0122_cache_his_dhcapp_sqluser`.`billdet`.`pbd_createdate` = (CAST((current_date()) AS VARCHAR))) AND (`hid0122_cache_his_dhcapp_sqluser`.`billdet`.`isdeleted` = '0')) AND ((length(`hid0122_cache_his_dhcapp_sqluser`.`billdet`.`pbd_totalamount`)) < 12)) AND (((`hid0122_cache_his_dhcapp_sqluser`.`adm`.`paadm_type` = 'I') OR ((`hid0122_cache_his_dhcapp_sqluser`.`adm`.`paadm_type` = 'O') AND (`hid0122_cache_his_dhcapp_sqluser`.`bill`.`pb_payedflag` = 'P'))) OR ((`hid0122_cache_his_dhcapp_sqluser`.`adm`.`paadm_type` = 'E') AND ((`hid0122_cache_his_dhcapp_sqluser`.`bill`.`pb_payedflag` = 'P') OR (`hid0122_cache_his_dhcapp_sqluser`.`adm`.`paadm_currentward_dr` IS NOT NULL))))
GROUP BY `hid0122_cache_his_dhcapp_sqluser`.`billdet`.`pbd_createdate`, `hid0122_cache_his_dhcapp_sqluser`.`adm`.`paadm_type`, `hid0122_cache_his_dhcapp_sqluser`.`tarec`.`tartec_desc`, `hid0122_cache_his_dhcapp_sqluser`.`ctloc`.`ctloc_code`, `hid0122_cache_his_dhcapp_sqluser`.`ctloc`.`ctloc_desc`, `hid0122_cache_his_dhcapp_sqluser`.`ctlocjs`.`ctloc_code`, `hid0122_cache_his_dhcapp_sqluser`.`ctlocjs`.`ctloc_desc`, `hid0122_cache_his_dhcapp_sqluser`.`ctlocjzks`.`ctloc_desc`, `hid0122_cache_his_dhcapp_sqluser`.`zyward`.`ward_desc`, `hid0122_cache_his_dhcapp_sqluser`.`ctlocjzks`.`ctloc_code`, `hid0122_cache_his_dhcapp_sqluser`.`zyward`.`ward_code`;
-- fsjcl_v2：放射/超声数据源仅 hid0101_mssql_*，公卫(hid0122)无对应 RIS/超声库，本期不 UNION
CREATE MATERIALIZED VIEW `indicators`.`fsjcl_v2` (`设备类型`, `患者类型`, `检查量`)
COMMENT "放射实时检查量"
DISTRIBUTED BY RANDOM
REFRESH ASYNC EVERY(INTERVAL 180 SECOND)
PROPERTIES (
"replicated_storage" = "true",
"replication_num" = "3",
"storage_medium" = "HDD"
)
AS SELECT `hid0101_mssql_ris_ris`.`v_rpt_full_study`.`f_modality_name` AS `设备类型`, `hid0101_mssql_ris_ris`.`v_rpt_full_study`.`f_psource_id` AS `患者类型`, count(*) AS `检查量`
FROM `hid0101_mssql_ris_ris`.`v_rpt_full_study`
WHERE (`hid0101_mssql_ris_ris`.`v_rpt_full_study`.`f_stu_exam_date` = (date_format(current_date(), '%Y.%m.%d'))) AND (`hid0101_mssql_ris_ris`.`v_rpt_full_study`.`f_stu_char409` != 'HID0104')
GROUP BY `hid0101_mssql_ris_ris`.`v_rpt_full_study`.`f_modality_name`, `hid0101_mssql_ris_ris`.`v_rpt_full_study`.`f_psource_id` UNION ALL SELECT '超声' AS `设备类型`, `hid0101_mssql_hxcs_hxcsrep`.`dic_pattype`.`PATTYPE_NAME` AS `患者类型`, sum(ceil(CAST(`hid0101_mssql_hxcs_hxcsrep`.`biz_exam`.`Exam_ScheduleTime` AS DOUBLE))) AS `检查量`
FROM `hid0101_mssql_hxcs_hxcsrep`.`biz_exam` INNER JOIN `hid0101_mssql_hxcs_hxcsrep`.`dic_pattype` ON `hid0101_mssql_hxcs_hxcsrep`.`dic_pattype`.`PATTYPE_GUID` = `hid0101_mssql_hxcs_hxcsrep`.`biz_exam`.`EXAM_PAT_PATTYPE_GUID`
WHERE ((((substring(`hid0101_mssql_hxcs_hxcsrep`.`biz_exam`.`Exam_verified_Datetime`, 1, 10)) = (CAST((current_date()) AS VARCHAR))) AND (`hid0101_mssql_hxcs_hxcsrep`.`biz_exam`.`Exam_Hosp_code` IN ('F0017', 'HID0101'))) AND (`hid0101_mssql_hxcs_hxcsrep`.`biz_exam`.`Exam_Disabled` = 'AA==')) AND (`hid0101_mssql_hxcs_hxcsrep`.`biz_exam`.`Exam_verified` = 'AQ==')
GROUP BY `hid0101_mssql_hxcs_hxcsrep`.`dic_pattype`.`PATTYPE_NAME`;
CREATE MATERIALIZED VIEW `indicators`.`jfyjgzl_v2` (`医院编码`, `医院名称`, `医嘱编码`, `医嘱名称`, `医嘱表执行日期`, `医嘱状态`, `支付状态`, `医嘱子类编码`, `医嘱子类名称`, `就诊类型`, `开医嘱日期`, `账单时间`, `开单数量`)
COMMENT "实时缴费医技工作量"
DISTRIBUTED BY RANDOM
REFRESH ASYNC EVERY(INTERVAL 180 SECOND)
PROPERTIES (
"replicated_storage" = "true",
"replication_num" = "3",
"storage_medium" = "HDD"
)
AS SELECT 'hid0101' AS `医院编码`, '四川大学华西医院' AS `医院名称`, `arcitmmast`.`arcim_code` AS `医嘱编码`, `arcitmmast`.`arcim_desc` AS `医嘱名称`, `oeorditem`.`oeori_dateexecuted` AS `医嘱表执行日期`, `oecorderstatus`.`ostat_desc` AS `医嘱状态`, `patbillorder`.`pbd_billstatus` AS `支付状态`, `arcitemcat`.`arcic_code` AS `医嘱子类编码`, `arcitemcat`.`arcic_desc` AS `医嘱子类名称`, `paadm`.`paadm_type` AS `就诊类型`, `oeorditem`.`oeori_date` AS `开医嘱日期`, `patbillorder`.`pbd_billdate` AS `账单时间`, sum(CAST(`oeorditem`.`oeori_phqtyord` AS INT)) AS `开单数量`
FROM `hid0101_cache_his_dhcapp_sqluser`.`oe_orditem` AS `oeorditem` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`arc_itmmast` AS `arcitmmast` ON `arcitmmast`.`arcim_rowid` = `oeorditem`.`oeori_itmmast_dr` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`arc_itemcat` AS `arcitemcat` ON `arcitemcat`.`arcic_rowid` = `arcitmmast`.`arcim_itemcat_dr` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`oec_orderstatus` AS `oecorderstatus` ON `oecorderstatus`.`ostat_rowid` = `oeorditem`.`oeori_itemstat_dr` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`oe_order` AS `oeorder` ON `oeorder`.`oeord_rowid1` = `oeorditem`.`oeori_oeord_parref` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`pa_adm` AS `paadm` ON `paadm`.`paadm_rowid` = `oeorder`.`oeord_adm_dr` LEFT OUTER JOIN (SELECT `pbd`.`pbd_billdate`, `pbd`.`pbd_billstatus`, `patbillorder`.`pbo_oeori_dr`, row_number() OVER (PARTITION BY `patbillorder`.`pbo_oeori_dr` ORDER BY `patbillorder`.`pbo_rowid` DESC ) AS `number`
FROM `hid0101_cache_his_dhcapp_sqluser`.`dhc_patbillorder` AS `patbillorder` LEFT OUTER JOIN `hid0101_cache_his_dhcapp_sqluser`.`dhc_patbilldetails` AS `pbd` ON (`pbd`.`pbd_pbo_parref` = `patbillorder`.`pbo_rowid`) AND (`pbd`.`isdeleted` = '0')
WHERE `patbillorder`.`isdeleted` = '0') `patbillorder` ON (`patbillorder`.`pbo_oeori_dr` = `oeorditem`.`oeori_rowid`) AND (`patbillorder`.`number` = 1)
WHERE ((`arcitemcat`.`arcic_code` IN ('4', '20', '43', '71', '610', '0903')) AND (`patbillorder`.`pbd_billdate` = (CAST((current_date()) AS VARCHAR)))) AND (`oeorditem`.`isdeleted` = '0')
GROUP BY `arcitmmast`.`arcim_code`, `arcitmmast`.`arcim_desc`, `oeorditem`.`oeori_dateexecuted`, `oecorderstatus`.`ostat_desc`, `patbillorder`.`pbd_billstatus`, `arcitemcat`.`arcic_code`, `arcitemcat`.`arcic_desc`, `paadm`.`paadm_type`, `oeorditem`.`oeori_date`, `patbillorder`.`pbd_billdate` UNION ALL SELECT 'hid0122' AS `医院编码`, '四川大学华西医院锦城医院(四川省公共综合临床中心)' AS `医院名称`, `arcitmmast`.`arcim_code` AS `医嘱编码`, `arcitmmast`.`arcim_desc` AS `医嘱名称`, `oeorditem`.`oeori_dateexecuted` AS `医嘱表执行日期`, `oecorderstatus`.`ostat_desc` AS `医嘱状态`, `patbillorder`.`pbd_billstatus` AS `支付状态`, `arcitemcat`.`arcic_code` AS `医嘱子类编码`, `arcitemcat`.`arcic_desc` AS `医嘱子类名称`, `paadm`.`paadm_type` AS `就诊类型`, `oeorditem`.`oeori_date` AS `开医嘱日期`, `patbillorder`.`pbd_billdate` AS `账单时间`, sum(CAST(`oeorditem`.`oeori_phqtyord` AS INT)) AS `开单数量`
