CREATE MATERIALIZED VIEW `indicators`.`mzssxz_indicators_v2` (`hosp_code`, `ctloc_desc`, `ctloc_code`, `questatedr`, `paadm_type`, `ghl`, `lastupdatedttm`)
COMMENT "实时就诊挂号"
DISTRIBUTED BY HASH(`hosp_code`)
REFRESH ASYNC EVERY(INTERVAL 180 SECOND)
PROPERTIES (
"replicated_storage" = "true",
"replication_num" = "3",
"storage_medium" = "HDD"
)
AS SELECT 'HID0101' AS `hosp_code`, `hid0101_cache_his_dhcapp_sqluser`.`b`.`ctloc_desc`, `hid0101_cache_his_dhcapp_sqluser`.`b`.`ctloc_code`, `hid0101_cache_his_dhcapp_sqluser`.`a`.`questatedr`, `hid0101_cache_his_dhcapp_sqluser`.`adm`.`paadm_type`, count(1) AS `ghl`, current_timestamp() AS `lastupdatedttm`
